-- Data only, no schema change. "cms.posts" used to open music, films and series, games, software, forum moderation
-- and review moderation as well as the magazine. From this release it is the magazine alone. So that no existing
-- role loses anything, every role that holds it is given the permissions it used to imply. Safe to run twice: a
-- role that already holds one is left alone. Full-access roles ("*") need nothing.
UPDATE "Role" SET "permissions" = "permissions" || ',music.manage' WHERE (',' || replace("permissions", ' ', '') || ',') LIKE '%,cms.posts,%' AND NOT (',' || replace("permissions", ' ', '') || ',') LIKE '%,music.manage,%' AND NOT (',' || replace("permissions", ' ', '') || ',') LIKE '%,*,%';
